/** One server health owner, three native multipart heads and bounded attack channels. */
public final class Gorynych extends PathfinderMob implements Enemy {
 private static final EntityDataAccessor<Integer> STATE=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.INT),AGE=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.INT),CLEAN=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.INT),BODY=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.INT);
 private static final EntityDataAccessor<Boolean> WINGS=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.BOOLEAN),FLY=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.BOOLEAN),DUCK=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.BOOLEAN);
 private static final EntityDataAccessor<Float> HP=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.FLOAT);
 private static final EntityDataAccessor<CompoundTag> HEADS=SynchedEntityData.defineId(Gorynych.class,EntityDataSerializers.COMPOUND_TAG);
 public final GorynychHead[] parts=new GorynychHead[3];public UUID instance;public int node;private CompoundTag layout=new CompoundTag();
 private final int[] headAge=new int[3],headAction=new int[3],headRest=new int[3];private final LivingEntity[] headTarget=new LivingEntity[3];private final float[] yaw=new float[3],pitch=new float[3];
 private final ServerBossEvent bar=new ServerBossEvent(GorynychContent.text("boss"),BossEvent.BossBarColor.PURPLE,BossEvent.BossBarOverlay.NOTCHED_20);
 private final Set<UUID> effects=new HashSet<>();private final List<Vec3> marks=new ArrayList<>();private float pendingDamage;private boolean damagePass;private int bodyAge,bodyRest=80,patrolAt,airAge;private Vec3 bodyAim=Vec3.ZERO;private List<LivingEntity> nearby=List.of();private int nearbyAt=-100;private ServerPlayer grabbed;private int grabAge,grabHits;
 public Gorynych(EntityType<? extends Gorynych> type,Level level){super(type,level);setPersistenceRequired();xpReward=0;for(int i=0;i<3;i++)parts[i]=new GorynychHead(this,i);setId(ENTITY_COUNTER.getAndAdd(4)+1);}
 public static AttributeSupplier.Builder attributes(){return createMobAttributes().add(Attributes.MAX_HEALTH,1024).add(Attributes.MOVEMENT_SPEED,.23).add(Attributes.FOLLOW_RANGE,24).add(Attributes.ARMOR,12).add(Attributes.ARMOR_TOUGHNESS,6).add(Attributes.KNOCKBACK_RESISTANCE,1);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(STATE,0);b.define(AGE,0);b.define(CLEAN,0);b.define(BODY,0);b.define(WINGS,false);b.define(FLY,false);b.define(DUCK,false);b.define(HP,GorynychRules.HP);b.define(HEADS,new CompoundTag());}
 @Override protected void registerGoals(){goalSelector.addGoal(0,new FloatGoal(this));goalSelector.addGoal(2,new Goal(){ {setFlags(EnumSet.of(Flag.MOVE,Flag.LOOK));}@Override public boolean canUse(){return (state()==GorynychRules.GROUND||state()==GorynychRules.AIR&&!flying())&&getTarget()!=null;}@Override public void tick(){var t=getTarget();getLookControl().setLookAt(t,8,8);if(tickCount%20==0&&distanceToSqr(t)>90&&GorynychPlaces.loaded((ServerLevel)level(),getBoundingBox().inflate(40)))getNavigation().moveTo(t,.85);}});}
 public int state(){return entityData.get(STATE);}public int age(){return entityData.get(AGE);}public int cleanMask(){return entityData.get(CLEAN);}public boolean wings(){return entityData.get(WINGS);}public boolean flying(){return entityData.get(FLY);}public boolean ducking(){return entityData.get(DUCK);}public float logicalHealth(){return entityData.get(HP);}public int bodyAction(){return entityData.get(BODY);}public CompoundTag heads(){return entityData.get(HEADS);}
 public boolean fighting(){return state()==GorynychRules.GROUND||state()==GorynychRules.AIR;}
 private void state(int value){entityData.set(STATE,value);entityData.set(AGE,0);getNavigation().stop();setTarget(null);}
 public void configure(UUID id,CompoundTag record){instance=id;layout=record.copy();node=record.getInt("Node");entityData.set(HP,Math.clamp(record.getFloat("HP"),GorynychRules.FLOOR,GorynychRules.HP));entityData.set(CLEAN,record.getInt("Clean")&7);entityData.set(WINGS,record.getBoolean("Wings"));state(record.getInt("State"));if(state()==GorynychRules.TRANSFORM)entityData.set(AGE,record.getInt("Age"));if(state()==GorynychRules.CLEANSING&&cleanMask()==7)entityData.set(AGE,record.getInt("Age"));super.setHealth(1024*logicalHealth()/GorynychRules.HP);}
 @Override public boolean isMultipartEntity(){return true;}@Override public GorynychHead[] getParts(){return parts;}@Override public void setId(int id){super.setId(id);if(parts!=null)for(int i=0;i<parts.length;i++)if(parts[i]!=null)parts[i].setId(id+i+1);}
 @Override public void move(MoverType type,Vec3 delta){if(instance!=null&&level() instanceof ServerLevel w){var bounds=GorynychPlaces.bounds(layout);double r=getBbWidth()/2;delta=new Vec3(Math.clamp(getX()+delta.x,bounds.minX+r,bounds.maxX-r)-getX(),Math.clamp(getY()+delta.y,bounds.minY,bounds.maxY-getBbHeight())-getY(),Math.clamp(getZ()+delta.z,bounds.minZ+r,bounds.maxZ-r)-getZ());if(!GorynychPlaces.loaded(w,getBoundingBox().expandTowards(delta).inflate(1)))delta=Vec3.ZERO;}super.move(type,delta);}
 private void unbound(){var w=(ServerLevel)level();var n=new CompoundTag();n.putLong("Origin",blockPosition().asLong());n.putString("Rotation","NONE");n.putLong("Seed",getUUID().getLeastSignificantBits());var d=GorynychLedger.get(w);d.ensure(getUUID(),n);var row=d.row(getUUID());row.putBoolean("Standalone",true);row.putUUID("Boss",getUUID());configure(getUUID(),row);}
 public boolean candidate(LivingEntity t){return t!=null&&t.isAlive()&&t!=this&&t.level()==level()&&GorynychPlaces.bounds(layout).contains(t.position())&&org.slavicmyths.karachun.NightOwners.owner(t)!=null&&(!(t instanceof ServerPlayer p)||!p.isSpectator()&&!p.hasDisconnected());}
 private List<LivingEntity> targets(){if(tickCount-nearbyAt>=10){nearby=level().getEntitiesOfClass(LivingEntity.class,getBoundingBox().inflate(48,30,48),this::candidate);nearbyAt=tickCount;}return nearby.stream().filter(this::candidate).toList();}
 private void credit(Entity t){if(instance==null||!(level() instanceof ServerLevel w))return;UUID owner=org.slavicmyths.karachun.NightOwners.owner(t);if(owner!=null)GorynychLedger.get(w).participant(instance,owner);}
 private boolean hit(LivingEntity t,float amount,int type){if(!fighting()||!candidate(t)||!hasLineOfSight(t))return false;boolean ok=t.hurt(org.slavicmyths.combat.MythDamageSources.caused(type==0?"gorynych_mor":type==1?"gorynych_fire":"gorynych_impact",this),amount);if(ok){credit(t);if(type==1)t.igniteForSeconds(3);if(type==0)t.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.WEAKNESS,100));}return ok;}
 @Override public void tick(){super.tick();if(level().isClientSide){positionHeads();return;}if(instance==null)unbound();var w=(ServerLevel)level();entityData.set(AGE,age()+1);if(tickCount%10==0){var overhead=getBoundingBox().move(0,2,0);entityData.set(DUCK,!flying()&&(!layout.getBoolean("Standalone")&&node>=3||GorynychPlaces.loaded(w,overhead)&&!w.noCollision(this,overhead)));}positionHeads();
  if(tickCount%20==0){persist();if(!GorynychPlaces.bounds(layout).contains(position())){var back=GorynychPlaces.node(layout,node);if(GorynychPlaces.safe(w,this,back)){setPos(back);getNavigation().stop();}}
   var choices=targets();for(var p:new ArrayList<>(bar.getPlayers()))if(!candidate(p)||!fighting())bar.removePlayer(p);if(fighting())for(var t:choices)if(t instanceof ServerPlayer p)bar.addPlayer(p);var live=choices.stream().filter(this::hasLineOfSight).toList();setTarget(live.isEmpty()?null:live.get(Math.floorMod(tickCount/120,live.size())));if(state()==GorynychRules.PATROL&&getTarget()!=null){state(GorynychRules.GROUND);sound("roar_ground");}
   if(state()==GorynychRules.PURIFIED)for(String key:GorynychLedger.part(GorynychLedger.get(w).row(instance),"Participants").getAllKeys()){var p=w.getServer().getPlayerList().getPlayer(UUID.fromString(key));if(p!=null&&GorynychPlaces.bounds(layout).contains(p.position()))GorynychRewards.claim(p,instance);}
  }
  bar.setProgress(logicalHealth()/GorynychRules.HP);bar.setName(GorynychContent.text("health",Math.round(logicalHealth()),3600));
  if(state()==GorynychRules.PATROL||state()==GorynychRules.PURIFIED){patrol();if(tickCount%260==0)sound("ambient_low");return;}
  if(state()==GorynychRules.TRANSFORM){releaseGrab();if(age()>=20&&node>=3&&!surface()){entityData.set(AGE,19);return;}if(age()==40){entityData.set(WINGS,true);sound("wings_unfold");}if(age()>=GorynychRules.TRANSFORM_TICKS){if(surface()){state(GorynychRules.AIR);entityData.set(FLY,false);airAge=0;sound("land");}}return;}
  if(state()==GorynychRules.EXHAUSTED||state()==GorynychRules.CLEANSING){releaseGrab();setDeltaMovement(Vec3.ZERO);bar.removeAllPlayers();if(state()==GorynychRules.CLEANSING&&cleanMask()==7){if(tickCount%4==0)particle(2,position().add(0,2,0),18);if(age()>=GorynychRules.CLEANSE_TICKS){state(GorynychRules.PURIFIED);entityData.set(HP,GorynychRules.HP);super.setHealth(1024);entityData.set(WINGS,true);sound("purified_roar");persist();w.getServer().overworld().getDataStorage().save();}}return;}
  grabTick();if(state()==GorynychRules.AIR)flight();headTick();bodyTick();
 }
 private void patrol(){if(tickCount<patrolAt)return;patrolAt=tickCount+100;int next=switch(node){case 0->getRandom().nextBoolean()?1:3;case 1->getRandom().nextBoolean()?0:2;case 2->1;case 3->getRandom().nextBoolean()?0:4;case 4->3;case 5->6;case 6->5;case 7->8;default->7;};var p=GorynychPlaces.node(layout,next);if(GorynychPlaces.safe((ServerLevel)level(),this,p)&&GorynychPlaces.loaded((ServerLevel)level(),getBoundingBox().inflate(40))&&getNavigation().moveTo(p.x,p.y,p.z,.7))node=next;}
 private boolean surface(){var w=(ServerLevel)level();for(int i=0;i<3;i++){var p=GorynychPlaces.node(layout,i);if(!GorynychPlaces.safe(w,this,p))continue;boolean underground=getY()<BlockPos.of(layout.getLong("Origin")).getY()+70&&!layout.getBoolean("Standalone");if(underground||node>=3||!GorynychPlaces.safe(w,this,position())){particle(0,position(),30);sound("transform_start");setPos(p);particle(2,p,30);}node=i;return true;}return false;}
 private void flight(){airAge++;int cycle=airAge%400;boolean air=cycle>=200&&cycle<400;entityData.set(FLY,air);setNoGravity(air);if(!air){if(getY()>GorynychPlaces.node(layout,node).y+.5){var p=GorynychPlaces.node(layout,node);move(MoverType.SELF,new Vec3(0,-Math.min(.4,getY()-p.y),0));}if(cycle==0)sound("land");return;}
  getNavigation().stop();var center=GorynychPlaces.node(layout,1);double a=airAge*.015;var desired=center.add(Math.cos(a)*5,bodyAction()==7?3:8+Math.sin(a*.5)*2,Math.sin(a)*5);var delta=desired.subtract(position());if(delta.length()>0.1){delta=delta.normalize().scale(.22);if(GorynychPlaces.loaded((ServerLevel)level(),getBoundingBox().move(delta))&&level().noCollision(this,getBoundingBox().move(delta)))move(MoverType.SELF,delta);}if(tickCount%45==0)sound("wings_flap");
 }
 private int danger(){int count=bodyAction()==0?0:1;for(int a:headAction)if(a>0)count++;return count;}
 private void headTick(){var ts=targets().stream().filter(this::hasLineOfSight).toList();for(int h=0;h<3;h++){if(headRest[h]>0)headRest[h]--;var t=headTarget[h];if(!candidate(t)||!hasLineOfSight(t)){headTarget[h]=ts.isEmpty()?null:ts.get(Math.floorMod(h+tickCount/100,ts.size()));t=headTarget[h];}if(t!=null){var d=t.getEyePosition().subtract(parts[h].position());float target=(float)Math.toDegrees(Math.atan2(d.x,d.z));target=getYRot()+Math.clamp(Mth.wrapDegrees(target-getYRot()),-55,55);yaw[h]=Mth.approachDegrees(yaw[h],target,3);pitch[h]=Mth.approachDegrees(pitch[h],(float)-Math.toDegrees(Math.atan2(d.y,d.horizontalDistance())),2);}
   if(headAction[h]==0&&headRest[h]==0&&t!=null&&danger()<2){if(h==2&&distanceToSqr(t)>120)continue;headAction[h]=h==2?(getRandom().nextBoolean()?1:2):(getRandom().nextBoolean()?1:2);headAge[h]=0;sound(h==0?"head_mor_charge":h==1?"head_fire_charge":"head_predator_bite");}
   if(headAction[h]>0){headAge[h]++;int warning=h==2?20:headAction[h]==1?24:36;if(headAge[h]<warning&&tickCount%4==0)particle(h,parts[h].position().add(0,1,0),4);if(headAge[h]==warning&&t!=null&&candidate(t)&&hasLineOfSight(t)){if(h<2&&headAction[h]==1){shot(h,t.getEyePosition(),parts[h].position().add(0,1,0));sound(h==0?"head_mor_shot":"head_fireball");}else if(h==2&&distanceToSqr(t)<120){if(hit(t,11,2)&&headAction[h]==2&&t instanceof ServerPlayer p&&level().getGameTime()>=p.getPersistentData().getLong("GorynychGrabUntil"))grab(p);}}
    if(h<2&&headAction[h]==2&&headAge[h]>=warning&&headAge[h]<warning+60){Vec3 from=parts[h].position().add(0,1,0);double ry=Math.toRadians(yaw[h]);Vec3 direction=new Vec3(Math.sin(ry),0,Math.cos(ry));if(tickCount%4==0)for(int i=1;i<=18;i++)particle(h,from.add(direction.scale(i)),2);if(tickCount%10==0)for(var target:ts){var d=target.getEyePosition().subtract(from);double dot=d.normalize().dot(direction);if(d.length()<22&&dot>(h==0?.98:.88)&&visible(from,target.getEyePosition()))hit(target,4,h);}if(headAge[h]==warning){sound(h==0?"head_mor_shot":"head_fire_breath");if(t!=null)cloud(h,t.position(),3);}}
    if(headAge[h]>warning+(h<2&&headAction[h]==2?75:22)){headAction[h]=0;headRest[h]=h==2?100:h==0?400:480;headAge[h]=0;}
   }
  }if(tickCount%4==0){var n=new CompoundTag();for(int h=0;h<3;h++){n.putFloat("Yaw"+h,Mth.wrapDegrees(yaw[h]-getYRot()));n.putFloat("Pitch"+h,pitch[h]);n.putInt("Action"+h,headAction[h]);n.putInt("Age"+h,headAge[h]);}n.putInt("BodyAge",bodyAge);if(bodyAction()==2)n.putLongArray("Spikes",marks.stream().mapToLong(p->BlockPos.containing(p).asLong()).toArray());entityData.set(HEADS,n);}}
 private boolean visible(Vec3 from,Vec3 to){return level().clip(new ClipContext(from,to,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,this)).getType()==HitResult.Type.MISS;}
 private void bodyTick(){if(bodyRest>0)bodyRest--;if(bodyAction()==0){if(bodyRest==0&&getTarget()!=null&&danger()<2){int action=flying()?3+getRandom().nextInt(5):1+getRandom().nextInt(2);entityData.set(BODY,action);bodyAge=0;bodyAim=getTarget().position();marks.clear();if(action==2||action==3){int count=action==3?7:5;for(int i=0;i<count;i++){var p=bodyAim.add((i%3-1)*3,0,(i/3-1)*3);if(visible(getEyePosition(),p.add(0,1,0)))marks.add(p);}}sound(action==1||action==7?"tail_sweep":action==2?"ground_spikes_warn":action==3?"head_mor_charge":action==4?"head_fire_charge":action==5?"wind_gust":"dive");}return;}
  bodyAge++;int action=bodyAction();if(bodyAge<32&&tickCount%4==0){if(marks.isEmpty())particle(action==4?1:2,bodyAim,12);else for(var p:marks)particle(action==3?0:2,p,6);}
  if(bodyAge==32){if(action==1||action==7){for(var t:targets()){var d=t.position().subtract(position());double behind=d.normalize().dot(getLookAngle());if(d.length()<11&&behind<.35&&hit(t,12,2))t.knockback(.8,getX()-t.getX(),getZ()-t.getZ());}}else if(action==2){sound("ground_spikes_impact");for(var p:marks){for(int y=0;y<5;y++)particle(2,p.add(0,y,0),8);for(var t:targets())if(t.position().distanceToSqr(p)<2.25)hit(t,10,2);}}else if(action==3){for(var p:marks)shot(0,p.add(0,.2,0),position().add(0,2,0));}else if(action==5){for(var t:targets())if(distanceToSqr(t)<400&&t.position().subtract(position()).normalize().dot(bodyAim.subtract(position()).normalize())>.85&&hit(t,6,2)){var direction=t.position().subtract(position()).normalize();t.setDeltaMovement(t.getDeltaMovement().add(direction.scale(.7)).add(0,.3,0));t.hurtMarked=true;}cloud(2,bodyAim,3);}else if(action==6&&visible(position(),bodyAim.add(0,5,0))){var aim=bodyAim.add(0,1,0);Vec3 delta=aim.subtract(position());for(int i=0;i<10;i++){var step=delta.scale(.1);if(!level().noCollision(this,getBoundingBox().move(step)))break;move(MoverType.SELF,step);}for(var t:targets())if(distanceToSqr(t)<144)hit(t,12,2);sound("land");entityData.set(FLY,false);airAge=0;}}
  if(action==4&&bodyAge>=32&&bodyAge<=80&&bodyAge%12==8)shot(1,bodyAim.add(getRandom().nextInt(5)-2,1,getRandom().nextInt(5)-2),parts[1].position());
  if(bodyAge>100){entityData.set(BODY,0);bodyRest=flying()?160:300;}
 }
 private void shot(int type,Vec3 aim,Vec3 from){if(effects.size()>24)return;var shot=GorynychContent.SHOT.get().create(level());if(shot==null)return;shot.configure(this,type,from,aim);if(level().addFreshEntity(shot))effects.add(shot.getUUID());}
 public void cloud(int type,Vec3 p,int uses){if(effects.size()>24)return;var w=(ServerLevel)level();BlockPos at=BlockPos.containing(p);for(int i=0;i<16&&w.hasChunkAt(at)&&w.getBlockState(at.below()).isAir();i++)at=at.below();if(!w.hasChunkAt(at))return;var cloud=GorynychContent.CLOUD.get().create(w);if(cloud==null)return;cloud.configure(this,type,Vec3.atBottomCenterOf(at),uses);if(w.addFreshEntity(cloud))effects.add(cloud.getUUID());}
 private void positionHeads(){for(int h=0;h<3;h++){float angle=getYRot();double r=Math.toRadians(angle);double sideways=-(h-1)*1.875;boolean folded=state()>=GorynychRules.EXHAUSTED&&state()<GorynychRules.PURIFIED;double height=folded?1.5:ducking()?4:6.5;double forward=folded?6.4:ducking()?5.6:3.7;Vec3 p=position().add(Math.cos(r)*sideways-Math.sin(r)*forward,height,Math.sin(r)*sideways+Math.cos(r)*forward);parts[h].setPos(p);}}
 private void grab(ServerPlayer p){releaseGrab();grabbed=p;grabAge=grabHits=0;sound("head_predator_grab");}
 public void resistGrab(){if(grabbed!=null&&++grabHits>=3)releaseGrab();}
 private void grabTick(){if(grabbed==null)return;if(!candidate(grabbed)||grabbed.hasDisconnected()||grabbed.distanceToSqr(this)>225||++grabAge>GorynychRules.GRAB_MAX){releaseGrab();return;}var p=parts[2].position();if(visible(grabbed.position(),p)&&level().noCollision(grabbed,grabbed.getBoundingBox().move(p.subtract(grabbed.position())))){grabbed.connection.teleport(p.x,p.y,p.z,grabbed.getYRot(),grabbed.getXRot());grabbed.setDeltaMovement(Vec3.ZERO);grabbed.fallDistance=0;}if(grabAge%20==0)hit(grabbed,3,2);}
 private void releaseGrab(){if(grabbed!=null){grabbed.getPersistentData().putLong("GorynychGrabUntil",level().getGameTime()+GorynychRules.GRAB_IMMUNITY);grabbed.fallDistance=0;grabbed=null;}grabAge=grabHits=0;}
 public boolean grabbed(Player p){return grabbed==p;}
 @Override public boolean hurt(DamageSource source,float amount){if(level().isClientSide||!Float.isFinite(amount)||amount<=0||state()>=GorynychRules.EXHAUSTED||state()==GorynychRules.TRANSFORM)return false;if(source.getEntity() instanceof Gorynych)return false;if(!layout.getBoolean("Standalone")&&source.getEntity() instanceof LivingEntity attacker&&!candidate(attacker))return false;if(damagePass){boolean nested=super.hurt(source,amount);if(nested)credit(source.getEntity());return nested;}if(state()==GorynychRules.PATROL)state(GorynychRules.GROUND);pendingDamage=0;damagePass=true;super.setHealth(1024);boolean hit=super.hurt(source,amount);damagePass=false;entityData.set(HP,GorynychRules.remaining(logicalHealth(),pendingDamage));super.setHealth(1024*logicalHealth()/GorynychRules.HP);if(hit&&pendingDamage>0){credit(source.getEntity());resistGrab();}if(logicalHealth()<=GorynychRules.FLOOR)exhaust();else if(logicalHealth()<=GorynychRules.TRANSFORM_HP&&!wings()){stopAttacks();state(GorynychRules.TRANSFORM);sound("transform_start");}persist();return hit;}
 @Override public void setHealth(float value){if(damagePass){pendingDamage+=Math.max(0,getHealth()-value);super.setHealth(Math.max(1,value));}else super.setHealth(Math.max(1,value));}
 @Override public void die(DamageSource source){if(!level().isClientSide&&state()<GorynychRules.EXHAUSTED)exhaust();}
 @Override public void kill(){if(!level().isClientSide&&state()<GorynychRules.EXHAUSTED)exhaust();}
 private void exhaust(){stopAttacks();entityData.set(HP,GorynychRules.FLOOR);state(GorynychRules.EXHAUSTED);surface();entityData.set(FLY,false);setNoGravity(false);sound("exhausted");persist();}
 private void stopAttacks(){releaseGrab();getNavigation().stop();setTarget(null);entityData.set(BODY,0);for(int h=0;h<3;h++){headAction[h]=headAge[h]=0;headTarget[h]=null;}if(level() instanceof ServerLevel w){for(UUID id:effects){var e=w.getEntity(id);if(e!=null)e.discard();}effects.clear();}bar.removeAllPlayers();}
 public InteractionResult cleanse(Player player,InteractionHand hand,int head){if(level().isClientSide)return InteractionResult.SUCCESS;if(!(player instanceof ServerPlayer p)||!p.isAlive()||p.isSpectator()||!GorynychRules.canClean(state(),cleanMask(),head)||parts[head].distanceToSqr(p)>100)return InteractionResult.PASS;if(!layout.getBoolean("Standalone")&&!p.isCreative()&&!org.slavicmyths.serpenthill.HillEvents.protectedPlayer(p)){p.displayClientMessage(org.slavicmyths.serpenthill.HillContent.text("ward_needed"),true);return InteractionResult.FAIL;}var stack=p.getItemInHand(hand);Item required=head==0?org.slavicmyths.quest185.Quest185Content.POWDER.get():org.slavicmyths.sanctuary.SanctuaryContent.ITEMS.get(head==1?"purifying_ash":"purified_water_bottle").get();if(!stack.is(required)){p.displayClientMessage(GorynychContent.text("cleanse_"+head),true);return InteractionResult.FAIL;}stack.shrink(1);if(head==2){var bottle=new ItemStack(Items.GLASS_BOTTLE);if(!p.getInventory().add(bottle))p.drop(bottle,false);}credit(p);entityData.set(CLEAN,GorynychRules.clean(cleanMask(),head));state(GorynychRules.CLEANSING);sound(head==0?"cleanse_mor_head":head==1?"cleanse_fire_head":"cleanse_predator_head");particle(head,parts[head].position(),40);persist();p.getInventory().setChanged();((org.slavicmyths.equipment.mixin.FrostPlayerSaveInvoker)p.server.getPlayerList()).slavicmyths$saveFrost(p);p.serverLevel().getServer().overworld().getDataStorage().save();return InteractionResult.SUCCESS;}
 @Override protected InteractionResult mobInteract(Player p,InteractionHand hand){if(p instanceof ServerPlayer server&&state()==GorynychRules.PURIFIED){GorynychRewards.interact(server,instance);return InteractionResult.SUCCESS;}if(p instanceof ServerPlayer server&&state()>=GorynychRules.EXHAUSTED){server.displayClientMessage(GorynychContent.text("heads_hint"),true);return InteractionResult.SUCCESS;}return super.mobInteract(p,hand);}
 @Override public boolean isAlliedTo(Entity e){return state()>=GorynychRules.EXHAUSTED||super.isAlliedTo(e);}
 @Override public boolean canBeLeashed(){return false;}
 @Override public boolean canUsePortal(boolean allowPassengers){return false;}
 @Override public void checkDespawn(){}
 @Override protected void playStepSound(BlockPos at,net.minecraft.world.level.block.state.BlockState state){if(!flying())sound("step_heavy");}
 public void sound(String s){GorynychContent.sound(level(),blockPosition(),s);}
 public void particle(int type,Vec3 p,int amount){if(level() instanceof ServerLevel w)w.sendParticles(BreathCloud.particle(type),p.x,p.y,p.z,amount,.2,.15,.2,.01);}
 private void persist(){if(instance==null||!(level() instanceof ServerLevel w))return;var d=GorynychLedger.get(w);var n=d.row(instance);n.putUUID("Boss",getUUID());n.putLong("LastPosition",blockPosition().asLong());n.putFloat("HP",logicalHealth());n.putInt("State",state());n.putInt("Age",age());n.putInt("Clean",cleanMask());n.putBoolean("Wings",wings());n.putInt("Node",node);d.setDirty();effects.removeIf(id->w.getEntity(id)==null);}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(instance!=null){persist();n.putUUID("GorynychInstance",instance);}n.put("GorynychLayout",layout);n.putFloat("GorynychHP",logicalHealth());n.putInt("GorynychState",state());n.putInt("GorynychClean",cleanMask());n.putInt("GorynychAge",age());n.putBoolean("GorynychWings",wings());n.putInt("GorynychNode",node);}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);instance=n.hasUUID("GorynychInstance")?n.getUUID("GorynychInstance"):null;layout=n.getCompound("GorynychLayout");node=n.getInt("GorynychNode");entityData.set(HP,n.contains("GorynychHP")?Math.clamp(n.getFloat("GorynychHP"),180,3600):3600);entityData.set(CLEAN,n.getInt("GorynychClean")&7);entityData.set(WINGS,n.getBoolean("GorynychWings"));state(n.getInt("GorynychState"));entityData.set(AGE,n.getInt("GorynychAge"));if(instance!=null&&level() instanceof ServerLevel w){var row=GorynychLedger.get(w).row(instance);if(row.contains("Origin"))configure(instance,row);}super.setHealth(1024*logicalHealth()/3600);stopAttacks();}
 @Override public void remove(RemovalReason reason){if(!level().isClientSide){stopAttacks();if(reason==RemovalReason.UNLOADED_TO_CHUNK)persist();}super.remove(reason);}
}
